Here's an example of a Discord bot with a single `ban` command using Discord.js v14 as slash commands:

First, create a new project directory, initialize it with npm and install the required dependencies:

```bash
mkdir my-discord-bot && cd $_
npm init -y
npm install discord.js @discordjs/builders
```

Now, let us create a `main.js` file to set up our Discord bot and register the command:

```javascript
const { Client, SlashCommandBuilder } = require('discord.js');
const { Routes } = require('discord-api-types/v9');
const { REST } = require('@discordjs/rest');
require('dotenv').config();

const client = new Client({ intents: ['Guilds', 'GuildMessages'] });

client.login(process.env.DISCORD_BOT_TOKEN);

// Setup command registrations
const commands = [
  new SlashCommandBuilder()
    .setName('ban')
    .setDescription('Ban a user from the server')
    .addUserOption((option) =>
      option
        .setName('user')
        .setDescription('The user you want to ban')
        .setRequired(true)
    ),
];

async function deployCommands() {
  const rest = new REST({ version: '9' }).setToken(process.env.DISCORD_BOT_TOKEN);

  try {
    console.log('Started refreshing application (/) commands.');

    await rest.put(
      Routes.applicationCommands(client.user!.id),
      { body: commands },
    );

    console.log(`Successfully reloaded ${commands.length} application (/) commands.`);
  } catch (error) {
    console.error(error);
  }
}

client.once('ready', async () => {
  await deployCommands();

  console.log(`Logged in as ${client.user.tag}!`);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isChatInputCommand()) return;

  const command = commands.find(cmd => cmd.getName() === interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  }
  catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error while executing this command!', ephemeral: true });
  }
});

class BanCommand {
  async execute(interaction) {
    const { member, options } = interaction;
    const targetUser = member.guild.members.cache.get(options.get('user').value);

    if (!targetUser) {
      return await interaction.reply({ content: " couldn't find user to ban.", ephemeral: true });
    }

    if (targetUser.id === member.user.id) {
      return await interaction.reply({ content: "you can't ban yourself!", ephemeral: true });
    }

    await targetUser.ban({ reason: 'Specified reason.' });

    return interaction.reply({ content: `${targetUser.user.username} has been banned.`, ephemeral: true });
  }
}
```

