#include <cstdio>
#include <string>
#include <algorithm>
#include <utility>
#include "cmark_gfm.h" // includes cmark_parser and cmark_node enum definitions.

// This function converts input markdown text to HTML format.
std::string markdownToHtml(std::string &markdown) {
    // Initialize parser and allocate memory for the parsed document.
    struct cmark_parser context{};
    context.input_buffer = const_cast<char*>(markdown.data());
    context.input_size = static_cast<cmark_size_t>(markdown.length());
    auto parser = cmark_parser_new(&context);

    struct cmark_node* node;
    int ret;
    std::string result;

    while ((ret = cmark_parser_parse(parser, 0))) {
        node = cmark_parser_final_node(parser);
        if (!node) break; // error parsing

        char* output = NULL;
        size_t length = cmark_node_render(cmark_lang_commonmark, node, 0, &output);
        result.append(output, length);
        free(output);

        cmark_node_free(node);
    }

    cmark_parser_free(parser);

    // Add any necessary final touches (e.g., convert line breaks).
    result.replace(std::ranges::search_n(result, "\n\n", 2), std::ranges::min_element(result.begin() + std::ranges::search_n(result, "\n\n", 2), result.end(), [](char c1, char c2) { return c1 != c2; }), "\n<br/>\n");

    // Return converted HTML string.
    return result;
}
```

