```python
def is_prime(n):
    # handle edge cases (1 is not prime, and any number can be divided by itself)
    if n <= 1:
        return False
    if n == 2:
        return True

    # check for divisibility by integers from 2 through the square root of n
    for I in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
```

