int main() {
    std::string target_word;
    std::cout << "Enter the word you want to count: ";
    std::cin >> target_word;

    std::ifstream file("input.txt");
    if (!file) {
        std::cerr << "Error: Failed opening input.txt";
        return 1;
    }

    int count = 0;
    std::string current_line;
    while (std::getline(file, current_line)) {
        std::vector<std::string> words;
        std::size_t start = 0;
        std::size_t pos = 0;

        while ((pos = current_line.find(' ', start)) != std::string::npos) {
            words.push_back(current_line.substr(start, pos - start));
            start = pos + 1;
        }

        words.push_back(current_line.substr(start));

        count += std::count_if(words.begin(), words.end(), [target_word](const auto& word){
            return word == target_word;
        });
    }

    std::cout << "Number of occurrences of \"" << target_word << "\" : " << count << '\n';
    return 0;
}
