Here's one possible implementation of a queue using two stacks:

```python
from collections import deque

class QueueUsingTwoStacks:
    def __init__(self):
        self.stack_in = deque()
        self.stack_out = deque()

    def enqueue(self, data):
        self.stack_in.append(data)

    def dequeue(self):
        if not self._is_empty():
            # Check if a single stack (stack_out) is non-empty
            if len(self.stack_out) > 0:
                return self.stack_out.popoff()

            # If stack_out is empty, pop from stack_in and push to stack_out until stack_out has enough elements
            while len(self.stack_in) > 0:
                self.stack_out.append(self.stack_in.pop())

            # Dequeue the first element from stack_out
            return self.stack_out.popoff()

        raise Exception("Queue is empty")

    def _is_empty(self):
        # Check if either stack is empty
        return len(self.stack_in) == 0 and len(self.stack_out) == 0

# Example usage:
q = QueueUsingTwoStacks()
q.enqueue(1)
q.enqueue(2)
q.enqueue(3)
print(q.dequeue())  # Output: 1
print(q.dequeue())  # Output: 2
print(q.dequeue())  # Output: 3

try:
    q.dequeue()  # Raises exception "Queue is empty"
except Exception as e:
    print(e)
```

